async function loadImages(){const results=await Promise.all(Object.entries(assetRows).map(([layer,rows])=>[layer,rows.filter(a=>a.state==='active').map(a=>[a.layerKey,a.label])]).flatMap(([layer,rows])=>rows.map(([id])=>loadAsset(layer,id))));if(results.some(ok=>!ok)){$('loadError').hidden=false;$('loadError').textContent='部分素材加载失败，请刷新后重试。'}}
