function smoothPolygon(ctx,points){let n=points.length;ctx.beginPath();const mid=(a,b)=>[(a[0]+b[0])/2,(a[1]+b[1])/2];ctx.moveTo(...mid(points[n-1],points[0]));for(let i=0;i<n;i++)ctx.quadraticCurveTo(...points[i],...mid(points[i],points[(i+1)%n]));ctx.closePath()}
