function tintFor(name,rgb){const k=name+rgb.join(',');if(tints.has(k))return tints.get(k);const off=document.createElement('canvas');off.width=off.height=512;const ctx=off.getContext('2d'),data=new ImageData(new Uint8ClampedArray(masks[name].data),512,512),p=data.data;for(let i=0;i<p.length;i+=4){const lum=(.2126*p[i]+.7152*p[i+1]+.0722*p[i+2])/255;p[i]=lum*rgb[0];p[i+1]=lum*rgb[1];p[i+2]=lum*rgb[2]}ctx.putImageData(data,0,0);tints.set(k,off);if(tints.size>48)tints.delete(tints.keys().next().value);return off}
