function selectedConfig(){if(activeLayer==='background')return null;const id=assetId(state,activeLayer);return state.transforms[activeLayer][id]}
function updateSelection(){if(activeLayer==='background'){$('selection').hidden=true;return}const sel=$('selection'),wasHidden=sel.hidden,name=sourceName(activeLayer,assetId(state,activeLayer)),c=selectedConfig();sel.hidden=!selected||!c||!bounds[name];if(sel.hidden){if(!wasHidden&&!matchMedia('(prefers-reduced-motion: reduce)').matches){sel.hidden=false;const animation=sel.animate([{opacity:1},{opacity:0}],{duration:100});animation.onfinish=()=>{if(!selected)sel.hidden=true}}return}if(wasHidden&&!matchMedia('(prefers-reduced-motion: reduce)').matches)sel.animate([{opacity:0},{opacity:1}],{duration:140});const r=M.rect(bounds[name],c);Object.assign(sel.style,{left:r.x/10.24+'%',top:r.y/10.24+'%',width:r.w/10.24+'%',height:r.h/10.24+'%',transform:`rotate(${c.rotation||0}deg)`});sel.dataset.layer=activeLayer}
