async function refreshSharedConfig(){
 if(isDemo)return;
 if(configRefreshBusy||!editorSetupReady||document.hidden||navigator.onLine===false||dirty||saving||restoring||drag||historyStart!==null||document.activeElement?.matches('input,select,textarea'))return;
 const version=editVersion,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),5000);configRefreshBusy=true;
 try{const response=await editorFetch('/api/v1/config',{credentials:'same-origin',cache:'no-cache',headers:revision?{'If-None-Match':revision}:{},signal:controller.signal});if(response.status===304||!response.ok)return;const data=await response.json();if(version!==editVersion||dirty||saving||restoring||drag||historyStart!==null)return;const next=M.validate({...M.initial(),...data.config});const motion=serverMotion(data.config),nextBackground=readBackgroundConfig(data.config);if(data.config.motion)AvatarMotion.validate(data.config.motion);if(!response.headers.get('ETag'))return;if(equal(data.config,lastSaved))return;state.transforms=next.transforms;state.scheme=next.scheme;state.motion=motion;motionEdited=false;state.backgroundMotion=nextBackground;backgroundEdited=false;window.avatarBackgroundEditor?.refresh();lastSaved=data.config;revision=response.headers.get('ETag');undoStack.length=redoStack.length=0;updateHistory();syncMotionControls();refresh();syncStatus();}catch{/* Keep the last usable shared config. */}finally{clearTimeout(timer);configRefreshBusy=false;}
}
setInterval(refreshSharedConfig,2000);window.addEventListener('focus',refreshSharedConfig);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshSharedConfig()});

// Emphasis uses the same nonmodal layer inspector and existing serialized writer.
function syncEmphasisStatus(){
 const status=$('inspectorSyncStatus');if(!status)return;
 if(isDemo){status.textContent='仅本页预览，不保存';$('inspectorRetry').hidden=true;return;}
 status.textContent=conflict?'版本冲突，选择已保留。可读取服务端版本。':(!canWrite||syncError)?'同步暂未成功，选择已保留。可重试同步。':dirty||saving||uncertain?'正在自动同步…':'选择后自动同步';
 $('inspectorRetry').hidden=!(conflict||!canWrite||syncError);
}
function setupEmotionEmphasis(){
 const stage=$('stageCapture'),canvas=$('mainCanvas');
 const layerAt=event=>['mood','accessory','head'].find(layer=>hit(point(event),layer));
 const openLayer=layer=>{if(!layer||drag||restoring)return;activeLayer=layer;selected=true;syncControls();playSelectionFeedback(layer);$('materialPanel').returnFocus=canvas;openInspector();};
 stage.addEventListener('dblclick',event=>{if(event.target.closest('.handle'))return;const layer=layerAt(event);if(layer){event.preventDefault();openLayer(layer)}});
 canvas.addEventListener('keydown',event=>{if(event.key==='Enter'&&selected){event.preventDefault();openLayer(activeLayer)}});
 let down=null,lastTap=null;
 canvas.addEventListener('pointerdown',event=>{if(event.pointerType==='touch')down={x:event.clientX,y:event.clientY,time:performance.now(),id:event.pointerId}});
 stage.addEventListener('pointerup',event=>{if(event.pointerType!=='touch'||!down||down.id!==event.pointerId)return;const now=performance.now(),layer=layerAt(event),tap=now-down.time<300&&Math.hypot(event.clientX-down.x,event.clientY-down.y)<8&&layer;down=null;if(!tap){lastTap=null;return}if(lastTap&&lastTap.layer===layer&&now-lastTap.time<380&&Math.hypot(event.clientX-lastTap.x,event.clientY-lastTap.y)<24){lastTap=null;event.preventDefault();queueMicrotask(()=>openLayer(layer))}else lastTap={x:event.clientX,y:event.clientY,time:now,layer}});
 stage.addEventListener('pointercancel',()=>{down=lastTap=null});
 const holdLabel=$('moodHold').parentElement;if(holdLabel.firstChild?.nodeType===3)holdLabel.firstChild.textContent='强调时长（毫秒）';
}
